class MaliCensus(unittest.TestCase):
    def test_tables(self):
        sexes = mc.parse_sexes(TEXT)
        self.assertEqual(sexes["Bamako"], (2_095_300, 2_132_269, 4_227_569))
        self.assertEqual(sexes["Taoudenni"], (55_284, 45_074, 100_358))
        medians = mc.parse_medians(TEXT)
        self.assertEqual(medians["Kidal"], 20)
        self.assertEqual(medians["Nara"], 15)
        annex = mc.parse_annex(TEXT)
        self.assertEqual(annex["Kayes"]["total"], 1_826_564)
        self.assertEqual(annex["Bamako"]["groups"][0], (0, 4, 690_493))
        self.assertEqual(annex["Bamako"]["groups"][-1], (100, None, 394))
        mc.check_medians(annex, medians)

    def test_regions(self):
        sexes, medians, annex = mc.parse_sexes(TEXT), mc.parse_medians(TEXT), mc.parse_annex(TEXT)
        records, report = mc.region_records(sexes, medians, annex, ADMIN1)
        by = {r["name"]: r for r in records}
        self.assertEqual(by["Kayes"]["population"]["value"], 1_840_329 + 681_671 + 678_061)
        self.assertEqual(by["Tombouctou"]["population"]["value"], 974_278 + 100_358)
        self.assertEqual(by["Gao"]["population"]["value"], 727_517 + 318_876)
        self.assertEqual(by["Kidal"]["median_age"]["value"], 20.0)
        self.assertEqual(by["Kidal"]["sex_ratio"]["value"], round(1000 * 45_229 / 37_963))
        for name in ("Koulikouro", "Sikasso", "Segou", "Mopti", "Bamako"):
            self.assertNotIn("value", by[name]["population"])
            self.assertIn("regions of 2023", by[name]["median_age"]["note"])
        self.assertEqual(len(report), 5)

    def test_projection(self):
        data = {"regions": {"KAYES": (1_300_000.0, 1_310_000.0)},
                "cercles": [{"name": "KÉNIÉBA", "region": "KAYES", "men": 130_000.0,
                             "women": 120_000.0},
                            {"name": "KAYES", "region": "KAYES", "men": 300_000.0,
                             "women": 310_000.0}]}
        self.assertFalse(mc.copied(data))
        records, report = mc.projection_records(data, ADMIN1, ADMIN2)
        by = {r["name"]: r for r in records}
        self.assertEqual(len(records), 50)
        self.assertEqual(by["Kenieba"]["sex_ratio"]["value"], round(1000 * 130 / 120))
        self.assertIn("by region only", by["Kenieba"]["median_age"]["note"])
        self.assertNotIn("value", by["Bamako"]["sex_ratio"])
        self.assertEqual(len(report), 48)
        shared = {"regions": {"KAYES": (100.0, 100.0)},
                  "cercles": [{"name": n, "region": "KAYES", "men": 50.0, "women": 50.0}
                              for n in ("A", "B", "C")]}
        self.assertTrue(mc.copied(shared))

    def test_cercles(self):
        data = {"cercles": [
            {"name": "KÉNIÉBA", "region": "KAYES", "median": 15.2, "men": 100, "women": 98,
             "total": 198, "unstated": 2},
            {"name": "BAMAKO", "region": "BAMAKO", "median": 19.9, "men": 900, "women": 910,
             "total": 1810, "unstated": 30}], "regions": {}, "blank": []}
        records, report = mc.cercle_records(data, ADMIN1, ADMIN2)
        by = {r["name"]: r for r in records}
        self.assertEqual(by["Kenieba"]["sex_ratio"]["value"], round(1000 * 100 / 98))
        self.assertEqual(by["Bamako"]["median_age"]["value"], 19.9)
        self.assertIn("1.0% whose age was not stated", by["Kenieba"]["median_age_note"])
        self.assertEqual(len([line for line in report if "no 2009 row" in line]), 48)


