class MaliRegionsOfBefore(unittest.TestCase):
    def test_crossed_regions_take_the_2009_census(self):
        sexes, medians, annex = mc.parse_sexes(TEXT), mc.parse_medians(TEXT), mc.parse_annex(TEXT)
        records, report = mc.region_records(sexes, medians, annex, ADMIN1, FACTS_2009)
        by = {r["name"]: r for r in records}
        koulikoro = by["Koulikouro"]
        self.assertEqual(koulikoro["median_age"]["value"], 15.6)
        self.assertEqual(koulikoro["median_age"]["year"], 2009)
        self.assertEqual(koulikoro["sex_ratio"]["value"], round(1000 * 1_200_000 / 1_218_305))
        self.assertIn("as it stood before 2023", koulikoro["sex_ratio_note"])
        self.assertIn("Ouélessébougou", koulikoro["median_age_note"])
        self.assertIn("2009", koulikoro["sources"][0]["name"])
        self.assertIn("district as drawn here", by["Bamako"]["median_age_note"])
        # The 2009 census's count of the region as drawn: older than OCHA's
        # 2018 sum, which the map shows, saying which figure it replaces.
        self.assertEqual(koulikoro["population"]["value"], 2_418_305)
        self.assertEqual(koulikoro["population"]["year"], 2009)
        self.assertIn("as it stood before 2023", koulikoro["population_note"])
        self.assertIn("population", koulikoro["sources"][0]["field"].split("/"))
        # A crossed region the Bureau gives no figures for still says why.
        self.assertIn("cannot be put together", by["Mopti"]["median_age"]["note"])

    def test_bamako_takes_the_projection_of_its_own_ground(self):
        # The district drawn as one cercle: INSTAT's 2018 projection of its
        # ground, the figure its cercle carries, newer than the 2009 count,
        # which the note names. Koulikoro, drawn with several cercles, keeps
        # the 2009 count (the map shows its cercles' newer sum in its place).
        sexes, medians, annex = mc.parse_sexes(TEXT), mc.parse_medians(TEXT), mc.parse_annex(TEXT)
        projection = {"regions": {"BAMAKO": (1_100_000, 1_131_344)},
                      "totals": {"BAMAKO": 2_231_344, "KOULIKORO": 2_985_338},
                      "cercles": []}
        records, report = mc.region_records(sexes, medians, annex, ADMIN1, FACTS_2009,
                                            ADMIN2, projection)
        by = {r["name"]: r for r in records}
        bamako = by["Bamako"]
        self.assertEqual(bamako["population"]["value"], 2_231_344)
        self.assertEqual(bamako["population"]["year"], 2018)
        self.assertIn("projection for 2018", bamako["population_note"])
        self.assertIn("1,810,366", bamako["population_note"])
        cited = {s["name"]: s["field"].split("/") for s in bamako["sources"]}
        self.assertEqual(cited[mc.SOURCE_2018], ["population"])
        self.assertEqual(cited[mc.SOURCE_2009], ["median_age", "sex_ratio", "population note"])
        # Every note says what the 2022 census counts, and Bamako's measures the
        # district of 2023 by OCHA's boundaries: both are cited for the notes.
        notes = ["population note", "median_age note", "sex_ratio note"]
        self.assertEqual(cited[mc.SOURCE], notes)
        self.assertEqual(cited[mc.COD_AB_2023["name"]], notes)
        koulikoro = by["Koulikouro"]
        self.assertEqual(koulikoro["population"]["value"], 2_418_305)
        self.assertEqual(koulikoro["population"]["year"], 2009)
        self.assertNotIn(mc.COD_AB_2023["name"], {s["name"] for s in koulikoro["sources"]})
        self.assertIn(mc.SOURCE, {s["name"] for s in koulikoro["sources"]})
        self.assertTrue(any("2018 projection 2,231,344" in line for line in report))

    def test_the_cercles_cite_what_their_reasons_quote(self):
        final = mc.parse_p1(P1_TEXT, P1_COUNTRY)
        records, _ = mc.projection_records(None, ADMIN1, ADMIN2, FACTS_2009, final)
        tessalit = {r["name"]: r for r in records}["Tessalit"]
        cited = {s["name"]: s["field"].split("/") for s in tessalit["sources"]}
        self.assertEqual(cited[mc.SOURCE_P1], ["sex_ratio"])
        self.assertEqual(cited[mc.TOME_1["name"]], ["median_age note"])
        self.assertEqual(cited[mc.SOURCE], ["median_age note", "sex_ratio note"])
        self.assertIn("Tome 1, Tableau P-2", tessalit["median_age"]["note"])
        # The compositions say why there are none, citing the report on the
        # census's cultural characteristics, which mali.py reads by region.
        self.assertEqual(cited[mc.CULTURE_2022["name"]],
                         ["religion note", "ethnicity note", "language note"])
        self.assertEqual(tessalit["religion"]["note"],
                         "The 2022 census tabulates religion by region only (Caractéristiques "
                         "culturelles de la population), not by cercle.")
        self.assertIn("mother tongue", tessalit["language"]["note"])
        from scripts.fetch_census import mali as ml
        self.assertEqual((mc.CULTURE_2022["name"], mc.CULTURE_2022["url"]), (ml.SOURCE, ml.URL))

    def test_bamako_drawn_as_one_cercle(self):
        data = {"regions": {}, "cercles": []}
        records, _ = mc.projection_records(data, ADMIN1, ADMIN2, FACTS_2009)
        by = {r["name"]: r for r in records}
        self.assertEqual(by["Bamako"]["median_age"]["value"], 19.4)
        self.assertIn("drawn as one cercle", by["Bamako"]["sex_ratio_note"])
        # Kati, in a crossed region of several cercles, takes nothing from it.
        self.assertNotIn("value", by["Kati"].get("sex_ratio", {}))

    def test_a_cercle_spelt_otherwise_is_paired_within_its_region(self):
        gao = next(s for s in ADMIN1 if s["name"] == "Gao")
        cercles = [s for s in ADMIN2 if s["parent"] == gao["id"]]
        data = {"regions": {}, "cercles": [
            {"name": "ANSONGHO" if c["name"] == "Ansongo" else c["name"].upper(),
             "region": "GAO", "men": 100.0, "women": 100.0} for c in cercles]}
        parents = {s["id"]: mc.fold(s["name"]).replace("koulikouro", "koulikoro") for s in ADMIN1}
        pairs = mc.paired(data, ADMIN2, parents)
        ansongo = next(c for c in cercles if c["name"] == "Ansongo")
        self.assertEqual(pairs[ansongo["id"]]["name"], "ANSONGHO")
        self.assertEqual(len([c for c in cercles if c["id"] in pairs]), len(cercles))


    def test_the_final_count_by_cercle(self):
        final = mc.parse_p1(P1_TEXT, P1_COUNTRY)
        by = {c["name"]: c for c in final["cercles"]}
        self.assertEqual((by["Tessalit"]["men"], by["Tessalit"]["women"]), (8_424, 7_531))
        self.assertEqual(final["regions"]["KIDAL"], (36_335, 31_404, 67_739))
        self.assertEqual(by["Bamako"]["total"], 1_810_366)
        # A cercle misread no longer makes its region.
        with self.assertRaises(SystemExit):
            mc.parse_p1(P1_TEXT.replace("8 424 7 531 15 955", "8 425 7 531 15 956"),
                        P1_COUNTRY)
        records, report = mc.projection_records(None, ADMIN1, ADMIN2, FACTS_2009, final)
        rec = {r["name"]: r for r in records}
        tessalit = rec["Tessalit"]
        self.assertEqual(tessalit["sex_ratio"]["value"], round(1000 * 8_424 / 7_531))
        self.assertEqual(tessalit["sex_ratio"]["year"], 2009)
        self.assertIn("8,424 men and 7,531 women", tessalit["sex_ratio_note"])
        self.assertEqual(tessalit["sources"][0]["field"], "sex_ratio")
        self.assertIn("Tableau P-1", tessalit["sources"][0]["name"])
        self.assertEqual(rec["Tin-Essako"]["sex_ratio"]["value"], round(1000 * 4_394 / 3_628))
        # Bamako, a crossed district drawn as one cercle, keeps its own figures.
        self.assertIn("drawn as one cercle", rec["Bamako"]["sex_ratio_note"])

